'use strict';

const fs = require('fs');
const path = require('path');

// Generated by frontend/scripts/gen-company-plan-data.mjs. The account stores the answers, never the task list,
// so a content fix reaches people who already have a plan.
const DATA_PATH = path.resolve(__dirname, '../../cdn/questions/company-plan-data.json');

const LEVELS = new Set(['junior', 'mid', 'senior', 'staff']);
const WHENS = new Set(['tomorrow', 'this-week', 'next-week', 'later']);
const MAX_COMPANIES = 3;
const MAX_PASSED_ROUNDS = 60;
const MAX_MARKED_DONE = 200;
const SLUG = /^[a-z0-9]+(?:-[a-z0-9]+)*$/;
const ROUND_KEY = /^[a-z0-9]+(?:-[a-z0-9]+)*\/[a-z0-9]+(?:-[a-z0-9]+)*\/[a-z0-9]+(?:-[a-z0-9]+)*$/;
const TASK_ID = /^\/?[a-z0-9]+(?:[-/][a-z0-9]+)*$/;

let cache = null;
let warnedMissing = false;

/**
 * What the data file allows, or null when it cannot be read. A missing file must not stop a buyer from saving a
 * plan, so the answers then pass on their shape alone and the screens ignore a company they do not know.
 */
function loadCompanyPlanCatalog(filePath = DATA_PATH) {
  let signature;
  try {
    const stats = fs.statSync(filePath);
    signature = `${filePath}:${stats.size}:${stats.mtimeMs}`;
  } catch {
    if (!warnedMissing) {
      warnedMissing = true;
      console.warn(`[company-plan] ${filePath} is missing, so plans are checked by shape only.`);
    }
    return null;
  }
  if (cache?.signature === signature) return cache.catalog;

  const data = JSON.parse(fs.readFileSync(filePath, 'utf8'));
  const companies = new Map();
  for (const [slug, company] of Object.entries(data.companies || {})) {
    const lists = new Map();
    for (const list of company.variants || []) {
      lists.set(list.id, new Set((list.rounds || []).map((round) => round.id)));
    }
    companies.set(slug, lists);
  }
  const catalog = { companies, taskIds: new Set(Object.keys(data.tasks || {})) };
  cache = { signature, catalog };
  return catalog;
}

function isPlainObject(value) {
  return Boolean(value) && typeof value === 'object' && !Array.isArray(value);
}

function parseCompany(entry, catalog) {
  if (!isPlainObject(entry) || typeof entry.slug !== 'string' || !SLUG.test(entry.slug)) {
    return { error: 'Each company needs a valid slug.' };
  }
  const lists = catalog?.companies.get(entry.slug);
  if (catalog && !lists) return { error: `Unknown company: ${entry.slug}.` };
  if (entry.list === undefined || entry.list === null) return { value: { slug: entry.slug } };
  if (typeof entry.list !== 'string' || !SLUG.test(entry.list)) return { error: `Invalid list for ${entry.slug}.` };
  if (lists && !lists.has(entry.list)) return { error: `Unknown list for ${entry.slug}: ${entry.list}.` };
  return { value: { slug: entry.slug, list: entry.list } };
}

/** Checks the form answers. The result holds only known fields, so nothing else in the body reaches the database. */
function parseCompanyPlanAnswers(body, catalog) {
  if (!isPlainObject(body)) return { error: 'The plan must be an object.' };
  const { companies, level, when } = body;
  if (!Array.isArray(companies) || companies.length < 1 || companies.length > MAX_COMPANIES) {
    return { error: `A plan needs 1 to ${MAX_COMPANIES} companies.` };
  }
  if (typeof level !== 'string' || !LEVELS.has(level)) return { error: 'Unknown level.' };
  if (typeof when !== 'string' || !WHENS.has(when)) return { error: 'Unknown interview date.' };

  const parsed = [];
  for (const entry of companies) {
    const company = parseCompany(entry, catalog);
    if (company.error) return { error: company.error };
    if (parsed.some((other) => other.slug === company.value.slug)) return { error: `Repeated company: ${company.value.slug}.` };
    parsed.push(company.value);
  }
  return { value: { companies: parsed, level, when } };
}

function sameCompanies(a, b) {
  const slugs = (list) => list.map((company) => company.slug).sort().join(',');
  return slugs(a) === slugs(b);
}

/**
 * The plan to store after new answers. The clock restarts only when the date answer or the companies change, so
 * switching a round list keeps "Week of Nov 9". Passed rounds of a dropped company go; manual marks stay.
 */
function nextCompanyPlan(previous, answers, now) {
  const before = typeof previous?.toObject === 'function' ? previous.toObject() : previous;
  const keepClock = Boolean(before?.createdAt) && before.when === answers.when && sameCompanies(before.companies || [], answers.companies);
  const kept = new Set(answers.companies.map((company) => company.slug));
  return {
    ...answers,
    createdAt: keepClock ? before.createdAt : now,
    passedRounds: (before?.passedRounds || []).filter((key) => kept.has(String(key).split('/')[0])),
    markedDone: before?.markedDone || [],
  };
}

/** Checks one "Mark as passed" or "done" toggle against the plan it changes. */
function parseCompanyPlanMark(body, plan, catalog) {
  if (!isPlainObject(body)) return { error: 'The mark must be an object.' };
  const { kind, id, on } = body;
  if (typeof on !== 'boolean') return { error: 'on must be true or false.' };
  if (typeof id !== 'string') return { error: 'id is required.' };

  if (kind === 'round') {
    if (!ROUND_KEY.test(id)) return { error: 'Invalid round.' };
    const [slug, listId, roundId] = id.split('/');
    if (!(plan.companies || []).some((company) => company.slug === slug)) return { error: 'That company is not in this plan.' };
    if (catalog && !catalog.companies.get(slug)?.get(listId)?.has(roundId)) return { error: 'Unknown round.' };
    if (on && !plan.passedRounds?.includes(id) && (plan.passedRounds?.length || 0) >= MAX_PASSED_ROUNDS) return { error: 'Too many passed rounds.' };
    return { value: { field: 'companyPlan.passedRounds', id, on } };
  }

  if (kind === 'task') {
    if (!TASK_ID.test(id)) return { error: 'Invalid task.' };
    if (catalog && !catalog.taskIds.has(id)) return { error: 'Unknown task.' };
    if (on && !plan.markedDone?.includes(id) && (plan.markedDone?.length || 0) >= MAX_MARKED_DONE) return { error: 'Too many marked tasks.' };
    return { value: { field: 'companyPlan.markedDone', id, on } };
  }

  return { error: 'kind must be round or task.' };
}

module.exports = {
  LEVELS,
  WHENS,
  loadCompanyPlanCatalog,
  nextCompanyPlan,
  parseCompanyPlanAnswers,
  parseCompanyPlanMark,
};
